 readonly Func<string,JsonObject?,CancellationToken,Task<JsonNode>> worker;string? path,sha,importId;Dictionary<string,string> assetPaths=new();List<BoardNodeRow> rows=new();JsonObject? snapshot,semantics;bool busy;Task selectionTask=Task.CompletedTask,evidenceTask=Task.CompletedTask;int selectionVersion;double originX,originY;Dictionary<string,Border> boxes=new();
 public BoardWindow(Func<string,JsonObject?,CancellationToken,Task<JsonNode>> worker){this.worker=worker;InitializeComponent();Loaded+=async(_,_)=>{Localizer.Apply(this,Localizer.Language);await Run(async()=>{var list=(await worker("board_list",new(),default)).AsArray();if(list.Count>0){var result=await worker("board_get",new(){["id"]=list.Last()!["id"]!.ToString()},default);await LoadImported(result.AsObject());}if(Environment.GetCommandLineArgs().Contains("--smoke-board")){SmokeCapture.Save(this,"board-ui","board.png");Search.Text="Philipp";NextMatch(this,new RoutedEventArgs());await selectionTask;await evidenceTask;SmokeCapture.Save(this,"board-ui","person-source.png");Search.Clear();Nodes.SelectedItem=rows.FirstOrDefault(r=>r.Data["id"]?.ToString()=="1:1742");await selectionTask;await evidenceTask;Zoom.Value=80;if(Nodes.SelectedItem is BoardNodeRow selected)Center(selected);SmokeCapture.Save(this,"board-ui","incorrect-connection.png");Close();}});};}
 async Task Run(Func<Task> action){if(busy)return;busy=true;try{await action();}catch(Exception ex){Status.Text=Localizer.Text(ex.Message);}finally{busy=false;}}
 async void OpenSnapshot(object sender,RoutedEventArgs e){var dialog=new OpenFileDialog{Filter="JSON (*.json)|*.json"};if(dialog.ShowDialog()!=true)return;await Run(async()=>{path=dialog.FileName;var result=await worker("board_preview",new(){["path"]=path},default);sha=result["sha"]!.ToString();importId=null;semantics=null;assetPaths.Clear();snapshot=result["raw"]!.AsObject();ShowNodes();Status.Text=Localizer.Text("Виберіть вузли людей перед імпортом. Примітки та стрілки зберігаються без припущень.");});}
 async void ImportBoard(object sender,RoutedEventArgs e)=>await Run(async()=>{if(path==null||sha==null)return;var people=new JsonArray();foreach(var row in rows.Where(r=>r.Person))people.Add(row.Data["id"]!.ToString());var args=new JsonObject{["path"]=path,["sha"]=sha,["people"]=people};var manifest=System.IO.Path.Combine(System.IO.Path.GetDirectoryName(path)!,"asset-manifest.json");if(System.IO.File.Exists(manifest))args["assets"]=manifest;var result=await worker("board_import",args,default);await LoadImported(result.AsObject());Status.Text=Localizer.Text("Дошку збережено. Родинні зв’язки потребують окремої перевірки.");});
 async Task LoadImported(JsonObject result){var folder=System.IO.Path.Combine(System.IO.Path.GetTempPath(),"ArchiveReader-board-"+result["id"]!.ToString());var exported=await worker("board_get",new(){["id"]=result["id"]!.ToString(),["export"]=folder},default);assetPaths.Clear();foreach(var asset in exported["assets"]!.AsArray().Where(a=>a!["kind"]!.ToString()=="render"))assetPaths[asset!["node"]!.ToString()]=asset["path"]!.ToString();Display(exported.AsObject());}
 void Display(JsonObject result){importId=result["id"]!.ToString();snapshot=result["snapshot"]!.AsObject();semantics=result["semantics"]?.AsObject();ShowNodes();var mapping=result["persons"]!.AsObject();foreach(var row in rows){row.Person=mapping.ContainsKey(row.Data["id"]!.ToString());row.Mapped=row.Person;}ApplySearch();Fit();}
 string NodeName(string? id){var n=rows.FirstOrDefault(r=>r.Data["id"]?.ToString()==id)?.Data;if(n==null)return Localizer.Text("Кінець на полотні");var text=n["text"]?.ToString();return string.IsNullOrWhiteSpace(text)?Localizer.Text("Фото")+" · "+n["name"]:text.Split('\n')[0];}
 void ShowNodes(){rows=snapshot!["nodes"]!.AsArray().Select(n=>new BoardNodeRow{Data=n!.AsObject(),CanPerson=(n["type"]?.ToString() is "TEXT" or "SHAPE_WITH_TEXT")&&!string.IsNullOrWhiteSpace(n["text"]?.ToString())}).ToList();foreach(var row in rows){var n=row.Data;row.Label=n["type"]?.ToString()=="CONNECTOR"?NodeName(n["start"]?["endpointNodeId"]?.ToString())+" → "+NodeName(n["end"]?["endpointNodeId"]?.ToString()):(!string.IsNullOrWhiteSpace(n["text"]?.ToString())?n["text"]!.ToString().Split('\n')[0]:Localizer.Text("Фото")+" · "+n["name"]);}ApplySearch();Draw();}
 void ApplySearch(){if(Nodes==null||Search==null)return;var query=Search.Text.Trim();Nodes.ItemsSource=rows.Where(r=>(PeopleOnly?.IsChecked!=true||r.Mapped)&&(query.Length==0||r.Label.Contains(query,StringComparison.CurrentCultureIgnoreCase)||(r.Data["text"]?.ToString().Contains(query,StringComparison.CurrentCultureIgnoreCase)??false))).ToList();}
 void SearchChanged(object sender,RoutedEventArgs e)=>ApplySearch();
 void SearchKey(object sender,KeyEventArgs e){if(e.Key==Key.Enter){NextMatch(sender,e);e.Handled=true;}}
 void NextMatch(object sender,RoutedEventArgs e){if(Nodes.Items.Count==0)return;Nodes.SelectedIndex=(Nodes.SelectedIndex+1)%Nodes.Items.Count;if(Nodes.SelectedItem is BoardNodeRow row){Nodes.ScrollIntoView(row);Zoom.Value=Math.Max(70,Zoom.Value);Center(row);}}
 void ClearSearch(object sender,RoutedEventArgs e){Search.Clear();PeopleOnly.IsChecked=false;}
 void ZoomChanged(object sender,RoutedPropertyChangedEventArgs<double> e){if(BoardScale==null)return;BoardScale.ScaleX=BoardScale.ScaleY=Zoom.Value/100;ZoomLabel.Text=((int)Zoom.Value)+"%";}
 void ZoomIn(object sender,RoutedEventArgs e){Zoom.Value=Math.Min(200,Zoom.Value*1.25);if(Nodes.SelectedItem is BoardNodeRow row)Center(row);}
 void ZoomOut(object sender,RoutedEventArgs e){Zoom.Value=Math.Max(5,Zoom.Value/1.25);if(Nodes.SelectedItem is BoardNodeRow row)Center(row);}
 void Fit(){if(Board.Width>0&&Board.Height>0){Viewport.UpdateLayout();Zoom.Value=Math.Clamp(Math.Min(Math.Max(100,Viewport.ViewportWidth)/Board.Width,Math.Max(100,Viewport.ViewportHeight)/Board.Height)*95,5,200);Viewport.ScrollToHorizontalOffset(0);Viewport.ScrollToVerticalOffset(0);}}
 void FitBoard(object sender,RoutedEventArgs e)=>Fit();
 void Center(BoardNodeRow row){Viewport.UpdateLayout();double factor=Zoom.Value/100;Viewport.ScrollToHorizontalOffset((Number(row.Data,"x")+Number(row.Data,"width")/2-originX+20)*factor-Viewport.ViewportWidth/2);Viewport.ScrollToVerticalOffset((Number(row.Data,"y")+Number(row.Data,"height")/2-originY+20)*factor-Viewport.ViewportHeight/2);}
 static double Number(JsonObject n,string key)=>n[key]?.GetValue<double>()??0;
 void Draw(){Board.Children.Clear();boxes.Clear();if(rows.Count==0)return;double minX=rows.Min(r=>Number(r.Data,"x")),minY=rows.Min(r=>Number(r.Data,"y"));originX=minX;originY=minY;const double scale=1;Board.Width=(rows.Max(r=>Number(r.Data,"x")+Number(r.Data,"width"))-minX)*scale+40;Board.Height=(rows.Max(r=>Number(r.Data,"y")+Number(r.Data,"height"))-minY)*scale+40;
 foreach(var row in rows){var n=row.Data;if(n["type"]!.ToString()=="CONNECTOR"){Point Endpoint(string key,bool last){var endpoint=n[key]?.AsObject();var target=rows.FirstOrDefault(r=>r.Data["id"]?.ToString()==endpoint?["endpointNodeId"]?.ToString());if(target!=null)return new Point((Number(target.Data,"x")+Number(target.Data,"width")/2-minX)*scale+20,(Number(target.Data,"y")+Number(target.Data,"height")/2-minY)*scale+20);var position=endpoint?["position"]?.AsObject();return new Point(((position!=null?Number(position,"x"):Number(n,"x")+(last?Number(n,"width"):0))-minX)*scale+20,((position!=null?Number(position,"y"):Number(n,"y")+(last?Number(n,"height"):0))-minY)*scale+20);}var p=Endpoint("start",false);var q=Endpoint("end",true);var edge=semantics?["connectors"]?[n["id"]!.ToString()];var c=edge?["color"];byte Channel(string key)=>(byte)Math.Clamp((c?[key]?.GetValue<double>()??.7)*255,0,255);var line=new Line{X1=p.X,Y1=p.Y,X2=q.X,Y2=q.Y,Stroke=new SolidColorBrush(Color.FromRgb(Channel("r"),Channel("g"),Channel("b"))),StrokeThickness=3,ToolTip=row.Label+" · "+EdgeStatus(edge?["status"]?.ToString())};line.MouseLeftButtonDown+=(_,_)=>{Nodes.SelectedItem=row;Nodes.ScrollIntoView(row);};Board.Children.Add(line);continue;}var box=new Border{Width=Math.Max(35,Number(n,"width")*scale),Height=Math.Max(14,Number(n,"height")*scale),Background=n["type"]!.ToString()=="CONNECTOR"?Brushes.LightGray:Brushes.WhiteSmoke,BorderBrush=Brushes.SlateGray,BorderThickness=new Thickness(.5),Child=new TextBlock{Text=n["text"]?.ToString()??n["name"]?.ToString(),FontSize=14,TextWrapping=TextWrapping.Wrap},ToolTip=row.Label,Tag=row};if(assetPaths.TryGetValue(n["id"]!.ToString(),out var imagePath)){var bitmap=new BitmapImage();bitmap.BeginInit();bitmap.CacheOption=BitmapCacheOption.OnLoad;bitmap.UriSource=new Uri(imagePath);bitmap.EndInit();bitmap.Freeze();box.Child=new Image{Source=bitmap,Stretch=Stretch.Uniform};}box.MouseLeftButtonDown+=(_,e)=>{Nodes.SelectedItem=row;Nodes.ScrollIntoView(row);if(e.ClickCount==2 && box.Child is Image image)new Window{Owner=this,Title=row.Label,Width=1000,Height=800,Content=new ScrollViewer{HorizontalScrollBarVisibility=ScrollBarVisibility.Auto,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,Content=new Image{Source=image.Source,Stretch=Stretch.None}}}.ShowDialog();};Canvas.SetLeft(box,(Number(n,"x")-minX)*scale+20);Canvas.SetTop(box,(Number(n,"y")-minY)*scale+20);Board.Children.Add(box);boxes[n["id"]!.ToString()]=box;}}
 static string EdgeStatus(string? status)=>Localizer.Text(status switch{"incorrect"=>"Помилковий зв’язок","unresolved"=>"Невирішений зв’язок","logically_consistent"=>"Логічно узгоджений за дошкою",_=>"Статус не визначено"});
 void SelectNode(object sender,SelectionChangedEventArgs e){if(Nodes.SelectedItem is BoardNodeRow row)selectionTask=ShowNode(row);}
 async Task ShowNode(BoardNodeRow row){int version=++selectionVersion;Center(row);foreach(var pair in boxes)pair.Value.BorderBrush=pair.Key==row.Data["id"]!.ToString()?Brushes.DodgerBlue:Brushes.SlateGray;var n=row.Data;var edge=semantics?["connectors"]?[n["id"]!.ToString()];Details.Text=n["type"]?.ToString()=="CONNECTOR"?row.Label+"\n\n"+EdgeStatus(edge?["status"]?.ToString())+"\n"+(edge?["origin"]?.ToString()=="manual_override"?edge?["reason"]?.ToString():Localizer.Text("Статус за кольором, указаним власником дошки."))+"\n"+Localizer.Text("Доказ для цього зв’язку показано окремо нижче."):(n["text"]?.ToString()??row.Label+"\n"+Localizer.Text("Фото з оригінальної дошки"));EvidenceRows.ItemsSource=null;EvidenceImage.Source=null;EvidenceText.Clear();if(importId==null)return;try{var result=await worker("board_evidence",new(){["id"]=importId,["node"]=n["id"]!.ToString()},default);if(version!=selectionVersion)return;var evidence=result.AsArray().Select(x=>new BoardEvidenceRow(x!.AsObject(),x["title"]?.ToString()??x["citation"]?.ToString()??Localizer.Text("Документ"))).ToList();EvidenceRows.ItemsSource=evidence;EvidenceRows.SelectedIndex=evidence.Count>0?0:-1;if(evidence.Count==0)EvidenceText.Text=Localizer.Text("Для цього вузла ще не прив’язано архівний запис. Фото дошки можна відкрити окремо.");}catch(Exception ex){if(version==selectionVersion)EvidenceText.Text=Localizer.Text(ex.Message);}}
 static BitmapImage LoadBitmap(string file){var bitmap=new BitmapImage();bitmap.BeginInit();bitmap.CacheOption=BitmapCacheOption.OnLoad;bitmap.UriSource=new Uri(file);bitmap.EndInit();bitmap.Freeze();return bitmap;}
 void SelectEvidence(object sender,SelectionChangedEventArgs e){if(EvidenceRows.SelectedItem is BoardEvidenceRow row)evidenceTask=ShowEvidence(row);}
 async Task ShowEvidence(BoardEvidenceRow row){try{var data=row.Data;string? file=data["preview"]?.ToString();bool crop=true;if(string.IsNullOrEmpty(file)&&data["page"]!=null){var rendering=await worker("render",new(){["id"]=data["page"]!.ToString()},default);file=rendering["path"]!.ToString();}if(!ReferenceEquals(EvidenceRows.SelectedItem,row))return;BitmapSource? image=string.IsNullOrEmpty(file)?null:LoadBitmap(file);if(crop&&image!=null&&data["rect"] is JsonArray rect&&rect.Count==4){double x=rect[0]!.GetValue<double>(),y=rect[1]!.GetValue<double>(),w=rect[2]!.GetValue<double>(),h=rect[3]!.GetValue<double>();int left=Math.Clamp((int)(x*image.PixelWidth),0,image.PixelWidth-1),top=Math.Clamp((int)(y*image.PixelHeight),0,image.PixelHeight-1);image=new CroppedBitmap(image,new Int32Rect(left,top,Math.Clamp((int)(w*image.PixelWidth),1,image.PixelWidth-left),Math.Clamp((int)(h*image.PixelHeight),1,image.PixelHeight-top)));image.Freeze();}EvidenceImage.Source=image;EvidenceText.Text=Localizer.Text(data["relationship_proof"]?.GetValue<bool>()==true?"Архівний доказ цього зв’язку":"Контекст людини або фото. Це саме по собі не доводить зв’язок.")+(data["stale"]?.GetValue<bool>()==true?"\n"+Localizer.Text("Запис змінився після прив’язування — перевірте доказ повторно."):"")+"\n\n"+(data["citation"]?.ToString()??"")+"\n\n"+(data["text"]?.ToString()??"");}catch(Exception ex){EvidenceText.Text=Localizer.Text(ex.Message);}}
 void ShowImage(ImageSource? source,string title){if(source==null)return;new Window{Owner=this,Title=title,Width=1000,Height=800,Content=new ScrollViewer{HorizontalScrollBarVisibility=ScrollBarVisibility.Auto,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,Content=new Image{Source=source,Stretch=Stretch.None}}}.ShowDialog();}
 void EnlargeEvidence(object sender,MouseButtonEventArgs e){if(e.ClickCount==2)ShowImage(EvidenceImage.Source,Localizer.Text("Документ і джерело"));}
 void OpenBoardPhoto(object sender,RoutedEventArgs e){if(Nodes.SelectedItem is not BoardNodeRow row)return;string? node=row.Data["id"]!.ToString();if(!assetPaths.ContainsKey(node)){node=new[]{row.Data["start"]?["endpointNodeId"]?.ToString(),row.Data["end"]?["endpointNodeId"]?.ToString()}.FirstOrDefault(id=>id!=null&&assetPaths.ContainsKey(id));}if(node!=null&&assetPaths.TryGetValue(node,out var file))ShowImage(LoadBitmap(file),row.Label);else Status.Text=Localizer.Text("Виберіть фото або зв’язок, що веде до фото.");}
 async void OpenFullScan(object sender,RoutedEventArgs e){if(EvidenceRows.SelectedItem is not BoardEvidenceRow row||row.Data["page"]==null)return;try{var result=await worker("render",new(){["id"]=row.Data["page"]!.ToString(),["full"]=true,["whole"]=true},default);ShowImage(LoadBitmap(result["path"]!.ToString()),Localizer.Text("Повний скан"));}catch(Exception ex){Status.Text=Localizer.Text(ex.Message);}}
 void OpenSource(object sender,RoutedEventArgs e){if(EvidenceRows.SelectedItem is not BoardEvidenceRow row)return;string? link=(row.Data["page_url"]??row.Data["url"]??row.Data["source_url"])?.ToString();if(Uri.TryCreate(link,UriKind.Absolute,out var uri)&&uri.Scheme is "https" or "http")Process.Start(new ProcessStartInfo(uri.AbsoluteUri){UseShellExecute=true});else Status.Text=Localizer.Text("Для цього джерела не вказано архівного посилання.");}
 async void ExportBoard(object sender,RoutedEventArgs e)=>await Run(async()=>{if(importId==null)return;var dialog=new OpenFolderDialog();if(dialog.ShowDialog()!=true)return;await worker("board_get",new(){["id"]=importId,["export"]=dialog.FolderName},default);Status.Text=Localizer.Text("Дошку та вкладення збережено.");});
